<template>
    <div>
        <Head title="Calendar" />

        <div class="text-center">
            <h3 class="title">FullCalendar.io</h3>
            <p class="category">
                Handcrafted by our friends from
                <a href="https://fullcalendar.io/" target="_blank" rel="noopener noreferrer">FullCalendar.io</a>.
                Please check out their
                <a href="https://fullcalendar.io/docs/vue" target="_blank" rel="noopener noreferrer">Vue documentation</a>.
            </p>
        </div>

        <div class="row">
            <div class="md:col-10 ms-auto me-auto">
                <Card class="card-calendar">
                    <FullCalendar ref="calendar" :options="calendarOptions" />
                </Card>
                <div class="d-flex flex-wrap align-items-center justify-content-between gap-2 mb-3">
                    <p class="mb-0">Select dates or time slots to add an event. Click an event for details. Drag events to move them, or drag their edges to resize. On touch screens, press and hold.</p>
                    <button type="button" class="btn btn-primary btn-sm m-0" @click="resetDemo">Reset demo</button>
                </div>
                <p class="fg-2">Demo changes stay in memory and are cleared when you leave or reload this page.</p>
                <p role="status" aria-live="polite">{{ feedback }}</p>
            </div>
        </div>

        <Modal ref="eventModal" title="Create an Event" :footer-close="false" @close="closeEventForm">
            <p>{{ selectedRange }}</p>
            <form id="calendar-event-form" @submit.prevent="createEvent">
                <label for="calendar-event-title">Event title</label>
                <input id="calendar-event-title" ref="eventTitle" v-model="eventTitle" class="form-control" type="text" maxlength="120" required :aria-invalid="Boolean(titleError)" :aria-describedby="titleError ? 'calendar-event-title-error' : undefined">
                <p v-if="titleError" id="calendar-event-title-error" class="fg-danger" role="alert">{{ titleError }}</p>
            </form>
            <template #footer>
                <button type="button" class="btn btn-link" @click="$refs.eventModal.hide()">Cancel</button>
                <button type="submit" form="calendar-event-form" class="btn btn-primary" :disabled="savingEvent">Create event</button>
            </template>
        </Modal>

        <Modal ref="detailsModal" :title="eventDetails?.title || 'Event details'" :footer-close="false" @close="eventDetails = null">
            <dl v-if="eventDetails" class="row mb-0">
                <dt class="col-4">Type</dt>
                <dd class="col-8">{{ eventDetails.allDay ? 'All-day event' : 'Timed event' }}</dd>
                <dt class="col-4">Starts</dt>
                <dd class="col-8">{{ formatEventDate(eventDetails.startTimestamp, eventDetails.allDay) }}</dd>
                <dt class="col-4">Ends</dt>
                <dd class="col-8">{{ eventDetailsEnd }}</dd>
            </dl>
            <template #footer>
                <button type="button" class="btn btn-primary" @click="$refs.detailsModal.hide()">Close</button>
            </template>
        </Modal>
    </div>
</template>

<script>
import { Head } from '@inertiajs/vue3';
import FullCalendar from '@fullcalendar/vue3';
import dayGridPlugin from '@fullcalendar/vue3/daygrid';
import timeGridPlugin from '@fullcalendar/vue3/timegrid';
import interactionPlugin from '@fullcalendar/vue3/interaction';
import { createCalendarTheme } from '@scaffold/lib/calendarTheme';
import '@fullcalendar/vue3/skeleton.css';
import '@fullcalendar/vue3/themes/classic/theme.css';
import '@fullcalendar/vue3/themes/classic/palette.css';
import Card from '@scaffold/components/Card.vue';
import Modal from '@scaffold/components/Modal.vue';

function demoEvents(today) {
    const year = today.getFullYear();
    const month = today.getMonth();
    const day = today.getDate();
    const date = (dayOfMonth, hour = null, minute = 0) => {
        const value = new Date(year, month, dayOfMonth, hour ?? 0, minute);
        const datePart = [value.getFullYear(), String(value.getMonth() + 1).padStart(2, '0'), String(value.getDate()).padStart(2, '0')].join('-');
        return hour === null ? datePart : `${datePart}T${String(hour).padStart(2, '0')}:${String(minute).padStart(2, '0')}:00`;
    };
    return [
        { id: 'all-day', title: 'All Day Event', start: date(1), allDay: true, theme: 'secondary' },
        { id: 'repeating-1', groupId: 'repeating', title: 'Repeating Event', start: date(day - 4, 6), theme: 'rose' },
        { id: 'repeating-2', groupId: 'repeating', title: 'Repeating Event', start: date(day + 3, 6), theme: 'rose' },
        { id: 'meeting', title: 'Meeting', start: date(day - 1, 10, 30), theme: 'success' },
        { id: 'lunch', title: 'Lunch', start: date(day + 7, 12), end: date(day + 7, 14), theme: 'danger' },
        { id: 'launch', title: 'Md-pro Launch', start: date(day - 2), allDay: true, theme: 'info' },
        { id: 'birthday', title: 'Birthday Party', start: date(day + 1, 19), end: date(day + 1, 22, 30), theme: 'info' },
    ].map(({ theme, ...event }) => ({
        ...event,
        color: `var(--${theme}-bg)`,
        contrastColor: '#fff',
    }));
}

export default {
    name: 'CalendarDemo',
    components: { Card, FullCalendar, Head, Modal },
    layout: { pageTitle: 'Calendar' },
    data() {
        const demoDate = new Date();
        return {
            demoDate,
            nextEventId: 1,
            pendingSelection: null,
            eventDetails: null,
            eventTitle: '',
            titleError: '',
            savingEvent: false,
            feedback: '',
            calendarOptions: {
                plugins: [createCalendarTheme({ buttonColorClass: 'btn-primary' }), dayGridPlugin, timeGridPlugin, interactionPlugin],
                initialView: 'dayGridMonth',
                headerToolbar: {
                    left: 'title',
                    center: 'dayGridMonth,timeGridWeek,timeGridDay',
                    right: 'prev,next today',
                },
                buttons: {
                    dayGridMonth: { text: 'month' },
                    timeGridWeek: { text: 'week' },
                    timeGridDay: { text: 'day' },
                    today: { text: 'today' },
                },
                aspectRatio: 1.35,
                dayMaxEvents: true,
                eventDisplay: 'block',
                nowIndicator: true,
                editable: true,
                selectable: true,
                selectMirror: true,
                select: this.openEventForm,
                eventClick: this.openEventDetails,
                eventDrop: this.eventMoved,
                eventResize: this.eventResized,
                events: demoEvents(demoDate),
            },
        };
    },
    computed: {
        eventDetailsEnd() {
            if (!this.eventDetails || this.eventDetails.endTimestamp === null) {
                return 'Not specified';
            }
            const end = new Date(this.eventDetails.endTimestamp);
            if (this.eventDetails.allDay) {
                end.setDate(end.getDate() - 1);
            }
            return this.formatEventDate(end.getTime(), this.eventDetails.allDay);
        },
        selectedRange() {
            if (!this.pendingSelection) {
                return '';
            }
            const { startTimestamp, endTimestamp, allDay } = this.pendingSelection;
            const start = new Date(startTimestamp);
            const end = new Date(endTimestamp);
            if (allDay) {
                end.setDate(end.getDate() - 1);
            }
            const formatter = new Intl.DateTimeFormat(undefined, {
                dateStyle: 'medium',
                ...(allDay ? {} : { timeStyle: 'short' }),
            });
            return `${allDay ? 'All day: ' : ''}${formatter.formatRange(start, end)}`;
        },
    },
    methods: {
        async openEventForm(selection) {
            if (this.pendingSelection || this.eventDetails) {
                return;
            }
            this.pendingSelection = {
                start: selection.startStr,
                end: selection.endStr,
                startTimestamp: selection.start.getTime(),
                endTimestamp: selection.end.getTime(),
                allDay: selection.allDay,
            };
            this.eventTitle = '';
            this.titleError = '';
            this.savingEvent = false;
            await this.showAfterInteraction('eventModal');
            this.$refs.eventTitle?.focus();
        },
        async showAfterInteraction(modalRef) {
            // Let FullCalendar finish its pointer-up handlers before a native dialog changes focus.
            await new Promise(resolve => requestAnimationFrame(resolve));
            await this.$refs[modalRef]?.show();
        },
        async openEventDetails({ event, jsEvent }) {
            jsEvent.preventDefault();
            if (this.pendingSelection || this.eventDetails) {
                return;
            }
            this.eventDetails = {
                title: event.title,
                startTimestamp: event.start.getTime(),
                endTimestamp: event.end?.getTime() ?? null,
                allDay: event.allDay,
            };
            await this.showAfterInteraction('detailsModal');
        },
        formatEventDate(timestamp, allDay) {
            return new Intl.DateTimeFormat(undefined, {
                dateStyle: 'medium',
                ...(allDay ? {} : { timeStyle: 'short' }),
            }).format(new Date(timestamp));
        },
        createEvent() {
            if (!this.pendingSelection || this.savingEvent) {
                return;
            }
            const title = this.eventTitle.trim();
            if (!title) {
                this.titleError = 'Enter an event title.';
                this.$refs.eventTitle.focus();
                return;
            }
            this.savingEvent = true;
            const { start, end, allDay } = this.pendingSelection;
            this.$refs.calendar.getApi().addEvent({
                id: `demo-created-${this.nextEventId++}`,
                title,
                start,
                end,
                allDay,
                color: 'var(--primary-bg)',
                contrastColor: '#fff',
            });
            this.feedback = `Created “${title}”.`;
            this.$refs.eventModal.hide();
        },
        closeEventForm() {
            this.$refs.calendar?.getApi().unselect();
            this.pendingSelection = null;
            this.eventTitle = '';
            this.titleError = '';
            this.savingEvent = false;
        },
        eventMoved({ event }) {
            this.feedback = `Moved “${event.title}” to ${new Intl.DateTimeFormat(undefined, { dateStyle: 'medium', ...(event.allDay ? {} : { timeStyle: 'short' }) }).format(event.start)}.`;
        },
        eventResized({ event }) {
            this.feedback = `Updated the duration of “${event.title}”.`;
        },
        resetDemo() {
            const calendar = this.$refs.calendar.getApi();
            calendar.unselect();
            calendar.batchRendering(() => {
                calendar.removeAllEvents();
                demoEvents(this.demoDate).forEach(event => calendar.addEvent(event));
            });
            this.feedback = 'Demo events restored. Your additions and date changes were cleared.';
        },
    },
};
</script>
